import React from 'react';
import {ThemeProvider} from '@gravity-ui/uikit';

import {loadTheme, saveTheme, type StoredTheme} from './theme-storage';

interface ThemeSwitcherContextValue {
  theme: StoredTheme;
  setTheme: (theme: StoredTheme) => void;
}

export const ThemeSwitcherContext = React.createContext<ThemeSwitcherContextValue | null>(null);

export function Root({children}: React.PropsWithChildren) {
  const [theme, setThemeState] = React.useState<StoredTheme>(loadTheme);

  const setTheme = React.useCallback((next: StoredTheme) => {
    setThemeState(next);
    saveTheme(next);
  }, []);

  const value = React.useMemo(() => ({theme, setTheme}), [theme, setTheme]);

  return (
    <ThemeSwitcherContext.Provider value={value}>
      <ThemeProvider theme={theme}>{children}</ThemeProvider>
    </ThemeSwitcherContext.Provider>
  );
}

export function useThemeSwitcher() {
  const ctx = React.useContext(ThemeSwitcherContext);
  if (!ctx) throw new Error('useThemeSwitcher must be used within Root');
  return ctx;
}
```

Hmm, writing saveTheme inside setTheme callback vs useEffect: effect is more idiomatic (single source of truth), but callback-write is simpler and avoids an extra write on mount. Either fine. I'll write in the callback (avoid redundant localStorage write on first render).

